// 3차 R2-B 브랜치 자동 개명(Orca autoRenameBranchFromWork — 기본 켬) — 순수 규칙(main·시험이 같이 읽는다).
// 출처: stablyai/orca @ec112c6b01 (MIT) src/shared/branch-name-from-work.ts(isAutoGeneratedCreatureBranchName·buildBranchNamePrompt·MAX_BRANCH_NAME_WORDS)
// · src/main/git/branch-rename.ts(resolveUniqueBranchName) · src/main/agent-hooks/first-work-generation-backoff.ts(재시도 간격).
// 흐름(main/scm/branchRename.ts): 작업 단위의 첫 지시 → 아라가 만든 작업 단위 · 자동 이름(바다 생물) 브랜치 · 아직 안 올린 브랜치일 때만
// CLI 에이전트로 이름을 지어 `git branch -m`. 사이드바 이름은 브랜치를 따른다(아라 displayName = 브랜치 이름).
import { MARINE_CREATURES } from './marineCreatures'

const CREATURES = new Set(MARINE_CREATURES.map((n) => n.toLowerCase()))

/** Orca isAutoGeneratedCreatureBranchName — 자동 이름(충돌 꼬리 -n 하나까지)만. 사람이 지은 브랜치는 절대 안 바꾼다. */
export function isAutoGeneratedCreatureBranchName(branchLeaf: string): boolean {
  const n = branchLeaf.trim().toLowerCase()
  return !!n && CREATURES.has(n.replace(/-\d+$/, ''))
}

/** Orca buildBranchNamePrompt(첫 지시 + 에이전트 첫 답 — 답은 아직 없을 수 있다). 사용자 지정 지시(customPrompt)는 뺐다. */
export function buildFirstWorkBranchNamePrompt(firstPrompt: string, assistantMessage?: string): string {
  const sections = ['Generate a short git branch name that summarizes the coding task described below.', 'Output ONLY the branch name on a single line, nothing else.', '', 'User request:', firstPrompt.trim()]
  const a = assistantMessage?.trim()
  if (a) sections.push('', "Agent's initial response:", a)
  return sections.join('\n')
}

/** Orca resolveUniqueBranchName — leaf, leaf-2, leaf-3 … 중 비어 있는 첫 이름(지금 브랜치는 충돌로 안 친다). 100번 넘으면 null. */
export async function resolveUniqueBranchName(leaf: string, exists: (name: string) => Promise<boolean>, currentBranch: string, maxAttempts = 100): Promise<string | null> {
  const free = async (c: string): Promise<boolean> => c === currentBranch || !(await exists(c))
  if (await free(leaf)) return leaf
  for (let n = 2; n <= maxAttempts; n += 1) if (await free(`${leaf}-${n}`)) return `${leaf}-${n}`
  return null
}

/** Orca FIRST_WORK_GENERATION_RETRY_DELAYS_MS — 이름 짓기가 실패하면(사용량 한도 등) 30초 → 2분 → 30분 뒤에야 다시. */
export const FIRST_WORK_RETRY_DELAYS_MS: readonly number[] = [30_000, 120_000, 1_800_000]
export const retryDelayOf = (failures: number): number => FIRST_WORK_RETRY_DELAYS_MS[Math.min(failures, FIRST_WORK_RETRY_DELAYS_MS.length) - 1] ?? 0
